#[path = "solution.rs"]
mod solution;

use solution::{add_authorization, authorize_or_decide, is_authorized, normalize_repository, TrustChoice, TrustPolicy};
use std::collections::BTreeSet;

fn empty_policy() -> TrustPolicy {
    TrustPolicy { organizations: BTreeSet::new(), repositories: BTreeSet::new() }
}

#[test]
fn normalization_trims_ascii_and_canonicalizes_case() {
    assert_eq!(normalize_repository(" \t Acme / Widget \r "), Some("acme/widget".to_string()));
    assert_eq!(normalize_repository("ORG/REPO"), Some("org/repo".to_string()));
    assert_eq!(normalize_repository("ÄCME/RÉPO"), Some("Äcme/rÉpo".to_string()));
}

#[test]
fn normalization_rejects_wrong_component_counts_and_empty_components() {
    for input in ["", "   ", "org", "/repo", "org/", "org//repo", "a/b/c"] {
        assert_eq!(normalize_repository(input), None, "input: {input:?}");
    }
}

#[test]
fn authorization_accepts_repository_or_organization_entries() {
    let mut policy = empty_policy();
    policy.repositories.insert("acme/widget".to_string());
    policy.organizations.insert("trusted".to_string());

    assert!(is_authorized(&policy, " ACME / WIDGET "));
    assert!(is_authorized(&policy, "Trusted/Anything"));
    assert!(!is_authorized(&policy, "other/widget"));
    assert!(!is_authorized(&policy, "trusted/extra/path"));
}

#[test]
fn adding_is_normalized_deduplicated_and_atomic_on_invalid_input() {
    let mut policy = empty_policy();
    policy.organizations.insert("existing-org".to_string());

    assert!(add_authorization(&mut policy, " Acme / Widget "));
    assert!(!add_authorization(&mut policy, "ACME/WIDGET"));
    assert_eq!(policy.repositories.len(), 1);
    assert!(policy.repositories.contains("acme/widget"));

    let before = policy.clone();
    assert!(!add_authorization(&mut policy, "bad/input/extra"));
    assert_eq!(policy, before);
}

#[test]
fn decisions_obey_interactivity_choice_and_mutation_rules() {
    let mut policy = empty_policy();

    let before_once = policy.clone();
    assert!(authorize_or_decide(&mut policy, "Org/Temporary", true, TrustChoice::Once));
    assert_eq!(policy, before_once);

    assert!(authorize_or_decide(&mut policy, "Org/Permanent", true, TrustChoice::Remember));
    assert!(policy.repositories.contains("org/permanent"));

    let before_authorized = policy.clone();
    assert!(authorize_or_decide(&mut policy, "ORG/PERMANENT", false, TrustChoice::Reject));
    assert_eq!(policy, before_authorized);

    let before_reject = policy.clone();
    assert!(!authorize_or_decide(&mut policy, "Org/Rejected", true, TrustChoice::Reject));
    assert_eq!(policy, before_reject);

    assert!(!authorize_or_decide(&mut policy, "Org/NonInteractive", false, TrustChoice::Remember));
    assert_eq!(policy, before_reject);
    assert!(!authorize_or_decide(&mut policy, "invalid", true, TrustChoice::Once));
    assert_eq!(policy, before_reject);
}

